#!/usr/bin/env bash
# Generated by OrchestKit Claude Plugin. Created: 2026-09-07
# /ork:page-serve stop: tear down one served page, or all of them.
#
#   stop.sh <name>     remove the portless alias, kill the static server, drop the
#                      state file and the screenshot
#   stop.sh --all      the same for every state file under .claude/state/page-serve/
#
# Reverse of serve.sh. The shared portless proxy daemon is never touched.
# Exit codes: 0 stopped (or nothing to stop), 1 usage, 2 portless missing.
#
# Every step reports its own result; a missing alias or an already-exited server is
# reported as such, not hidden, because "stopped" must mean the route is really gone.

set -euo pipefail

PROJECT_DIR="${CLAUDE_PROJECT_DIR:-$(pwd)}"
STATE_DIR="${PROJECT_DIR}/.claude/state/page-serve"

usage() { printf 'usage: stop.sh <name> | --all\n' >&2; exit 1; }
[[ $# -eq 1 ]] || usage

if ! command -v portless >/dev/null 2>&1; then
  printf 'stop.sh: portless is not installed; cannot remove aliases. State files left in place.\n' >&2
  exit 2
fi

stop_one() {
  local name="$1" f="${STATE_DIR}/$1.json" pid rc
  if [[ ! -f "$f" ]]; then
    printf 'stop.sh: no state for "%s" (nothing to stop)\n' "$name" >&2
    return 0
  fi
  pid="$(python3 -c 'import json,sys; print(json.load(open(sys.argv[1])).get("pid",0))' "$f")"

  local alias_out; alias_out="$(portless alias --remove "$name" 2>&1)"; rc=$?
  if [[ "$rc" == "0" ]]; then
    printf '  alias %s.localhost removed\n' "$name"
  else
    printf '  alias %s.localhost: portless reported rc=%s (%s); continuing\n' "$name" "$rc" "${alias_out:0:120}" >&2
  fi

  if [[ -n "$pid" && "$pid" != "0" ]]; then
    # silent: gating-relaxed (kill -0 is a liveness probe; an exited server is the expected "no")
    if kill -0 "$pid" 2>/dev/null; then
      local kill_out; kill_out="$(kill "$pid" 2>&1)"; rc=$?
      if [[ "$rc" == "0" ]]; then
        printf '  server pid %s stopped\n' "$pid"
      else
        printf '  server pid %s: kill rc=%s (%s). Left running; check ps.\n' "$pid" "$rc" "$kill_out" >&2
      fi
    else
      printf '  server pid %s was already gone\n' "$pid"
    fi
  fi

  rm -f "$f" "${STATE_DIR}/${name}.png" "${STATE_DIR}/${name}.log"
  printf 'stopped=%s\n' "$name"
}

if [[ "$1" == "--all" ]]; then
  found=0
  for f in "${STATE_DIR}"/*.json; do
    [[ -e "$f" ]] || continue
    found=1
    stop_one "$(basename "$f" .json)"
  done
  [[ "$found" == "1" ]] || printf 'stop.sh: nothing served\n' >&2
else
  stop_one "$1"
fi
